import { DarkTheme, DefaultTheme, ThemeProvider } from '@react-navigation/native';
import { Stack, useRouter, useSegments } from 'expo-router';
import { StatusBar } from 'expo-status-bar';
import { useEffect } from 'react';
import { ActivityIndicator, StyleSheet, View } from 'react-native';
import { SafeAreaProvider } from 'react-native-safe-area-context';
import 'react-native-reanimated';

import { ErrorBoundary } from '@/components/ranger/ErrorBoundary';
import { Brand } from '@/constants/theme';
import { useAuth } from '@/hooks/use-auth';
import { useAutoUpdate } from '@/hooks/use-auto-update';
import { useColorScheme } from '@/hooks/use-color-scheme';
import { useProfile } from '@/hooks/use-profile';
import { usePushToken } from '@/hooks/use-push-token';

export const unstable_settings = {
  anchor: '(tabs)',
};

// 社長(admin)が居てよいルート。それ以外に居たら /keiei へ戻す
const ADMIN_ALLOWED_ROOTS = new Set(['keiei', 'admin', 'admin-keiei', 'password-change', 'login']);

function AuthGate({ children }: { children: React.ReactNode }) {
  const { session, loading } = useAuth();
  const { profile, loading: profileLoading } = useProfile(session);
  const segments = useSegments();
  const router = useRouter();
  usePushToken(session);
  useAutoUpdate();

  const isAdmin = profile?.role === 'admin';

  useEffect(() => {
    if (loading || (session && profileLoading)) return;
    const onLoginScreen = segments[0] === 'login';
    if (!session && !onLoginScreen) {
      router.replace('/login');
    } else if (session && onLoginScreen) {
      router.replace(isAdmin ? '/keiei' : '/(tabs)');
    } else if (session && isAdmin && !ADMIN_ALLOWED_ROOTS.has(segments[0] ?? '')) {
      // 社長は経営管理画面の世界に固定（レンジャーUIは表示しない）
      router.replace('/keiei');
    }
  }, [session, loading, profileLoading, segments, router, isAdmin]);

  if (loading || (session && profileLoading)) {
    return (
      <View style={styles.loading}>
        <ActivityIndicator color={Brand.navy} />
      </View>
    );
  }

  return <>{children}</>;
}

export default function RootLayout() {
  const colorScheme = useColorScheme();

  return (
    <SafeAreaProvider>
      <ThemeProvider value={colorScheme === 'dark' ? DarkTheme : DefaultTheme}>
        <ErrorBoundary>
        <AuthGate>
          <Stack screenOptions={{ headerShown: false }}>
            <Stack.Screen name="login" />
            <Stack.Screen name="(tabs)" />
            <Stack.Screen name="keiei" />
            <Stack.Screen name="customer/[id]" />
            <Stack.Screen name="customer-edit/[id]" />
            <Stack.Screen name="prospect-new" />
            <Stack.Screen name="product/[id]" />
            <Stack.Screen name="ranger/[id]" />
            <Stack.Screen name="ranger-new" />
            <Stack.Screen name="ranger-edit/[id]" />
            <Stack.Screen name="admin" />
            <Stack.Screen name="admin-showroom" />
            <Stack.Screen name="notifications" />
            <Stack.Screen name="ranking" />
            <Stack.Screen name="showroom" />
            <Stack.Screen name="profile-edit" />
          </Stack>
        </AuthGate>
        </ErrorBoundary>
        <StatusBar style="auto" />
      </ThemeProvider>
    </SafeAreaProvider>
  );
}

const styles = StyleSheet.create({
  loading: { flex: 1, justifyContent: 'center', alignItems: 'center', backgroundColor: '#fff' },
});
