import { useCallback, useEffect, useState } from 'react';

import { fetchAll, supabase } from '@/lib/supabase';

/**
 * 経営管理シートv1: company_sales_monthly（全社月次×商品）を読み、
 * 売上ブロック・粗利ブロック用のKPIに集計する。
 * 粗利は標準原価（原価表）ベースの参考値。cost_source='candidate' は粗利計算から除外。
 */

type Row = {
  month: string;
  product_code: string;
  product_name: string | null;
  category: 'wholesale' | 'ec';
  amount_jpy: number;
  qty: number;
  cost_unit_jpy: number | null;
  cost_source: string | null;
};

export type MonthKpi = {
  month: string;          // 'YYYY-MM'
  total: number;          // 全社売上
  ec: number;             // EC売上（WEB商品）
  wholesale: number;      // 卸売上
  gpEst: number;          // 推定粗利額（原価紐づけ分のみ）
  coveredAmount: number;  // 原価紐づけ済み売上
};

export type ProductKpi = {
  code: string;
  name: string;
  amount: number;
  qty: number;
  costUnit: number | null;
  costSource: string | null;
  gpEst: number | null;   // null = 原価未紐づけ
  gpRate: number | null;
};

export type CompanyKpis = {
  months: MonthKpi[];
  totalSales: number;
  totalGpEst: number;
  coverageRate: number;      // 原価紐づけ済み売上 ÷ 全社売上（EC明細込み）
  latestMonth: MonthKpi | null;
  topProducts: ProductKpi[]; // 売上上位（全期間累計）
  unmappedTop: ProductKpi[]; // 原価未紐づけの売上上位
  lossTop: ProductKpi[];     // 逆ざや（粗利マイナス）の売上上位
  lossCount: number;
  unmappedAmount: number;    // 原価未紐づけの売上合計（卸のみ）
};

const GP_SOURCES = new Set(['code', 'manual', 'name', 'invoice']);

function costedGp(r: Row): number | null {
  if (r.cost_unit_jpy == null || !GP_SOURCES.has(r.cost_source ?? '')) return null;
  if (!(r.qty > 0)) return null;
  return r.amount_jpy - r.cost_unit_jpy * r.qty;
}

export function useCompanyKpis() {
  const [kpis, setKpis] = useState<CompanyKpis | null>(null);
  const [loading, setLoading] = useState(true);
  const [error, setError] = useState<string | null>(null);

  const load = useCallback(async () => {
    setLoading(true);
    setError(null);
    try {
      const { data: rows, error: fetchError } = await fetchAll<Row>(() =>
        supabase
          .from('company_sales_monthly')
          .select('month, product_code, product_name, category, amount_jpy, qty, cost_unit_jpy, cost_source')
          .order('id')
      );
      if (fetchError) throw new Error(fetchError);

      const byMonth = new Map<string, MonthKpi>();
      const byProduct = new Map<string, ProductKpi>();

      for (const r of rows) {
        const m = byMonth.get(r.month) ?? {
          month: r.month, total: 0, ec: 0, wholesale: 0, gpEst: 0, coveredAmount: 0,
        };
        m.total += r.amount_jpy;
        if (r.category === 'ec') m.ec += r.amount_jpy;
        else m.wholesale += r.amount_jpy;
        const gp = costedGp(r);
        if (gp != null) {
          m.gpEst += gp;
          m.coveredAmount += r.amount_jpy;
        }
        byMonth.set(r.month, m);

        if (r.category !== 'ec') {
          const p = byProduct.get(r.product_code) ?? {
            code: r.product_code,
            name: r.product_name ?? r.product_code,
            amount: 0, qty: 0,
            costUnit: r.cost_unit_jpy,
            costSource: r.cost_source,
            gpEst: null, gpRate: null,
          };
          p.amount += r.amount_jpy;
          p.qty += r.qty;
          if (r.product_name) p.name = r.product_name;
          byProduct.set(r.product_code, p);
        }
      }

      for (const p of byProduct.values()) {
        if (p.costUnit != null && GP_SOURCES.has(p.costSource ?? '') && p.qty > 0) {
          p.gpEst = p.amount - p.costUnit * p.qty;
          p.gpRate = p.amount > 0 ? p.gpEst / p.amount : null;
        }
      }

      const months = [...byMonth.values()].sort((a, b) => a.month.localeCompare(b.month));
      const products = [...byProduct.values()].sort((a, b) => b.amount - a.amount);
      const totalSales = months.reduce((s, m) => s + m.total, 0);
      const totalCovered = months.reduce((s, m) => s + m.coveredAmount, 0);
      const totalGpEst = months.reduce((s, m) => s + m.gpEst, 0);

      setKpis({
        months,
        totalSales,
        totalGpEst,
        coverageRate: totalSales > 0 ? totalCovered / totalSales : 0,
        latestMonth: months.length ? months[months.length - 1] : null,
        topProducts: products.slice(0, 10),
        unmappedTop: products.filter((p) => p.gpEst == null).slice(0, 5),
        lossTop: products.filter((p) => p.gpRate != null && p.gpRate < 0).slice(0, 5),
        lossCount: products.filter((p) => p.gpRate != null && p.gpRate < 0).length,
        unmappedAmount: products.filter((p) => p.gpEst == null).reduce((s, p) => s + p.amount, 0),
      });
    } catch (e) {
      setError(e instanceof Error ? e.message : 'データの取得に失敗しました');
    } finally {
      setLoading(false);
    }
  }, []);

  useEffect(() => {
    load();
  }, [load]);

  return { kpis, loading, error, reload: load };
}
