import * as ImagePicker from 'expo-image-picker';
import { Platform } from 'react-native';

import { supabase } from '@/lib/supabase';

// ネイティブの fetch(file://).blob() は 0 バイトの Blob を返すことがあり、
// 空ファイルが Storage に上がって「写真が貼れない」状態になる
// (松永さんFB 2026-07-10、実際に 0 バイトの jpg/png が2件上がっていた)。
// ネイティブでは ImagePicker の base64 を ArrayBuffer に変換してアップロードする。

/** Hermes に atob が無い環境でも動く純JSの base64 デコード */
function base64ToBytes(b64: string): Uint8Array {
  const table = 'ABCDEFGHIJKLMNOPQRSTUVWXYZabcdefghijklmnopqrstuvwxyz0123456789+/';
  const clean = b64.replace(/[^A-Za-z0-9+/]/g, '');
  const len = clean.length;
  const byteLen = Math.floor((len * 3) / 4);
  const bytes = new Uint8Array(byteLen);
  let p = 0;
  for (let i = 0; i < len; i += 4) {
    const a = table.indexOf(clean[i]);
    const b = table.indexOf(clean[i + 1]);
    const c = i + 2 < len ? table.indexOf(clean[i + 2]) : 0;
    const d = i + 3 < len ? table.indexOf(clean[i + 3]) : 0;
    const n = (a << 18) | (b << 12) | (c << 6) | d;
    if (p < byteLen) bytes[p++] = (n >> 16) & 0xff;
    if (p < byteLen) bytes[p++] = (n >> 8) & 0xff;
    if (p < byteLen) bytes[p++] = n & 0xff;
  }
  return bytes;
}

export type PickedImageAsset = {
  uri: string;
  base64?: string | null;
  mimeType?: string | null;
};

function resolveContentType(asset: PickedImageAsset): { contentType: string; ext: string } {
  const mime = (asset.mimeType ?? '').toLowerCase();
  if (mime.includes('png')) return { contentType: 'image/png', ext: 'png' };
  if (mime.includes('webp')) return { contentType: 'image/webp', ext: 'webp' };
  // HEIC はブラウザで表示できないため jpeg として扱う
  // (picker 側で preferredAssetRepresentationMode: 'compatible' を指定して JPEG 化する前提)
  return { contentType: 'image/jpeg', ext: 'jpg' };
}

/**
 * ImagePicker のアセットを Supabase Storage にアップロードして公開URLを返す。
 * pathPrefix はバケット内のフォルダ（例: customerId や user.id）。
 */
export async function uploadPickedImage(
  bucket: string,
  pathPrefix: string,
  asset: PickedImageAsset,
): Promise<string> {
  const { contentType, ext } = resolveContentType(asset);
  const path = `${pathPrefix}/${Date.now()}-${Math.random().toString(36).slice(2, 8)}.${ext}`;

  let body: ArrayBuffer | Blob;
  if (Platform.OS !== 'web' && asset.base64) {
    const bytes = base64ToBytes(asset.base64);
    if (bytes.byteLength === 0) throw new Error('画像データを読み込めませんでした（空データ）');
    body = bytes.buffer as ArrayBuffer;
  } else {
    const response = await fetch(asset.uri);
    const blob = await response.blob();
    if (blob.size === 0) throw new Error('画像データを読み込めませんでした（空データ）');
    body = blob;
  }

  const { error } = await supabase.storage.from(bucket).upload(path, body, { contentType, upsert: true });
  if (error) throw error;

  const { data } = supabase.storage.from(bucket).getPublicUrl(path);
  return data.publicUrl;
}

/**
 * ネイティブで base64 を確実に受け取るための ImagePicker 共通オプション。
 * - base64: ネイティブのみ（web は blob で読めるので不要）
 * - preferredAssetRepresentationMode 'compatible': iOS の HEIC を JPEG に変換
 */
export const pickerUploadOptions = {
  base64: Platform.OS !== 'web',
  preferredAssetRepresentationMode:
    ImagePicker.UIImagePickerPreferredAssetRepresentationMode.Compatible,
} as const;
