import { ScrollView, StyleSheet, Text, View } from 'react-native';
import { useSafeAreaInsets } from 'react-native-safe-area-context';

import { Card } from '@/components/ui/Card';
import { EmptyState } from '@/components/ui/EmptyState';
import { SectionTitle } from '@/components/ui/SectionTitle';
import { ShimmerCard } from '@/components/ui/Shimmer';
import { Accent, Brand, Ink, Radius } from '@/constants/theme';
import { useCompanyKpis, type MonthKpi, type ProductKpi } from '@/hooks/use-company-kpis';

/** 経営管理（詳細）— 月別推移・商品別粗利。スマホファースト */

function fmtShort(v: number): string {
  if (Math.abs(v) >= 1e8) return `${(v / 1e8).toFixed(1)}億`;
  return `${Math.round(v / 1e4)}万`;
}

function monthLabel(month: string): string {
  return `${parseInt(month.slice(5, 7), 10)}月`;
}

function BarChart({ months, pick, tone }: {
  months: MonthKpi[];
  pick: (m: MonthKpi) => number;
  tone: string;
}) {
  const max = Math.max(...months.map(pick), 1);
  return (
    <View style={styles.chartRow}>
      {months.map((m) => {
        const v = pick(m);
        return (
          <View key={m.month} style={styles.chartCol}>
            <View style={styles.barWrap}>
              <View style={[styles.bar, { backgroundColor: tone, height: Math.max(6, (v / max) * 110) }]} />
            </View>
            <Text style={styles.chartValue}>{fmtShort(v)}</Text>
            <Text style={styles.chartLabel}>{monthLabel(m.month)}</Text>
          </View>
        );
      })}
    </View>
  );
}

function ProductRow({ rank, p }: { rank: number; p: ProductKpi }) {
  const gpText = p.gpRate == null ? '—' : `${(p.gpRate * 100).toFixed(1)}%`;
  const gpColor =
    p.gpRate == null ? Ink[400] : p.gpRate < 0 ? Accent.red : p.gpRate < 0.15 ? Accent.amber : Accent.emerald;
  return (
    <View style={styles.productRow}>
      <Text style={styles.productRank}>{rank}</Text>
      <View style={{ flex: 1, minWidth: 0 }}>
        <Text style={styles.productName} numberOfLines={1}>{p.name}</Text>
        <Text style={styles.productAmount}>売上 ¥{Math.round(p.amount).toLocaleString()}</Text>
      </View>
      <Text style={[styles.productGp, { color: gpColor }]}>{gpText}</Text>
    </View>
  );
}

export default function KeieiKanriScreen() {
  const insets = useSafeAreaInsets();
  const { kpis, loading, error, reload } = useCompanyKpis();

  if (loading) {
    return (
      <View style={[styles.root, { paddingTop: insets.top + 16 }]}>
        <View style={styles.container}>
          <ShimmerCard />
          <ShimmerCard />
        </View>
      </View>
    );
  }

  if (error || !kpis || kpis.months.length === 0) {
    return (
      <View style={[styles.root, { paddingTop: insets.top + 16 }]}>
        <EmptyState icon="📈" title="経営管理データがありません" message={error ?? ''} actionLabel="再読み込み" onAction={reload} />
      </View>
    );
  }

  const latest = kpis.latestMonth!;
  const period = `${kpis.months[0].month.replace('-', '年')}月〜${latest.month.replace('-', '年')}月`;

  return (
    <ScrollView style={styles.root} contentContainerStyle={{ paddingTop: insets.top + 16, paddingBottom: 32 }}>
      <View style={styles.container}>
        <Text style={styles.title}>経営管理</Text>
        <Text style={styles.sub}>
          粗利は実質原価ベース（輸入品=原価表フルコスト、国内品=仕入実績、EC=makeshop受注明細）の参考値。データ期間: {period}
        </Text>

        {/* KPI 縦積み対応（スマホで2枚×wrap） */}
        <View style={styles.kpiRow}>
          <View style={styles.kpiCard}>
            <Text style={styles.kpiLabel}>累計売上</Text>
            <Text style={[styles.kpiValue, { color: Brand.navy }]}>{fmtShort(kpis.totalSales)}円</Text>
          </View>
          <View style={styles.kpiCard}>
            <Text style={styles.kpiLabel}>累計推定粗利</Text>
            <Text style={[styles.kpiValue, { color: Accent.emerald }]}>{fmtShort(kpis.totalGpEst)}円</Text>
          </View>
          <View style={styles.kpiCard}>
            <Text style={styles.kpiLabel}>原価カバー率</Text>
            <Text style={[styles.kpiValue, { color: Accent.amber }]}>{Math.round(kpis.coverageRate * 100)}%</Text>
          </View>
        </View>

        <SectionTitle title="月別売上推移" caption="全社（卸＋EC）" />
        <Card variant="surface" padding={16} style={{ marginBottom: 16 }}>
          <BarChart months={kpis.months} pick={(m) => m.total} tone={Brand.navy} />
        </Card>

        <SectionTitle title="月別推定粗利" caption={`全社売上の${Math.round(kpis.coverageRate * 100)}%をカバー`} />
        <Card variant="surface" padding={16} style={{ marginBottom: 16 }}>
          <BarChart months={kpis.months} pick={(m) => m.gpEst} tone={Accent.emerald} />
          <Text style={styles.note}>※ 原価が紐づいた売上のみ集計。</Text>
        </Card>

        <SectionTitle title="商品別売上TOP10" caption="累計・粗利率は実質原価ベース" />
        <Card variant="surface" padding={14} style={{ marginBottom: 16 }}>
          {kpis.topProducts.map((p, i) => (
            <ProductRow key={p.code} rank={i + 1} p={p} />
          ))}
        </Card>

        {kpis.unmappedTop.length > 0 ? (
          <Card variant="surface" padding={16} style={{ marginBottom: 16 }}>
            <Text style={styles.unmappedTitle}>⚠️ 原価未紐づけの主な商品</Text>
            {kpis.unmappedTop.map((p) => (
              <View key={p.code} style={styles.unmappedRow}>
                <Text style={styles.unmappedName} numberOfLines={1}>{p.name}</Text>
                <Text style={styles.unmappedAmount}>¥{Math.round(p.amount).toLocaleString()}</Text>
              </View>
            ))}
          </Card>
        ) : null}

        {/* サイクル起動の質問 */}
        <Card variant="surface" padding={18} style={styles.askCard}>
          <Text style={styles.askTitle}>💬 このシートに、他に何が見えると嬉しいですか？</Text>
          <Text style={styles.askBody}>
            例: 得意先別の粗利 ／ 値上げが必要な商品 ／ 担当者別の数字 ／ 在庫とのズレ など。
            言っていただければ次の更新で追加します。
          </Text>
        </Card>
      </View>
    </ScrollView>
  );
}

