import { useCallback, useEffect, useState } from 'react';

import { fetchAll, supabase } from '@/lib/supabase';
import type { SalesPhase } from '@/lib/sales-phase';

export type CustomerRow = {
  id: string;
  name: string;
  branch_name: string | null;
  address: string | null;
  business_type: string | null;
  status: string;
  image_url: string | null;
  last_ordered_at: string | null;
  sales_phase: SalesPhase | null;
  acquired_by_ranger_id: string | null;
  total_sales_jpy: number;
};

export type DerivedStatus = 'good' | 'stall' | 'follow';

/**
 * 最終発注日から表示用ステータスを算出する。
 * 将来 customers.status に 'good'/'stall'/'follow' を格納する場合はそちらを優先する。
 */
export function deriveStatus(lastOrderedAt: string | null | undefined): DerivedStatus {
  if (!lastOrderedAt) return 'follow';
  const days = Math.floor((Date.now() - new Date(lastOrderedAt).getTime()) / 86400000);
  if (days >= 30) return 'follow';
  if (days >= 14) return 'stall';
  return 'good';
}

export function useCustomers() {
  const [customers, setCustomers] = useState<CustomerRow[]>([]);
  const [loading, setLoading] = useState(true);
  const [error, setError] = useState<string | null>(null);
  const [reloadKey, setReloadKey] = useState(0);

  useEffect(() => {
    let mounted = true;
    setLoading(true);
    setError(null);
    Promise.all([
      fetchAll<Omit<CustomerRow, 'total_sales_jpy'>>(() =>
        supabase
          .from('customers')
          .select(
            'id, name, branch_name, address, business_type, status, image_url, last_ordered_at, sales_phase, acquired_by_ranger_id'
          )
          .order('last_ordered_at', { ascending: false, nullsFirst: false })
      ),
      fetchAll<{ customer_id: string; total_sales_jpy: number | string }>(() =>
        supabase.from('v_customer_sales').select('customer_id, total_sales_jpy')
      ),
    ]).then(([customersRes, salesRes]) => {
      if (!mounted) return;
      if (customersRes.error) {
        console.warn('[useCustomers]', customersRes.error);
        setError(customersRes.error);
      }
      if (salesRes.error) console.warn('[useCustomers:sales]', salesRes.error);

      const salesMap = new Map<string, number>(
        salesRes.data.map((r) => [r.customer_id, Number(r.total_sales_jpy ?? 0)])
      );
      const rows = customersRes.data.map((c) => ({
        ...c,
        total_sales_jpy: salesMap.get(c.id) ?? 0,
      }));
      setCustomers(rows);
      setLoading(false);
    });
    return () => {
      mounted = false;
    };
  }, [reloadKey]);

  const reload = useCallback(() => setReloadKey((k) => k + 1), []);
  return { customers, loading, error, reload };
}
