import { Image } from 'expo-image';
import { StyleSheet, Text, View, ViewStyle } from 'react-native';
import { Ink, Radius } from '@/constants/theme';

type Props = {
  imageUrl?: string | null;
  size?: number;
  radius?: number;
  style?: ViewStyle;
};

export function CustomerThumb({ imageUrl, size = 68, radius = Radius.md, style }: Props) {
  return (
    <View style={[styles.base, { width: size, height: size, borderRadius: radius }, style]}>
      {imageUrl ? (
        <View style={[styles.logoWrap, { width: size, height: size, padding: size * 0.14 }]}>
          <Image source={{ uri: imageUrl }} style={{ width: '100%', height: '100%' }} contentFit="contain" />
        </View>
      ) : (
        <View style={[styles.placeholder, { width: size, height: size }]}>
          <Text style={{ fontSize: size * 0.35 }}>🏪</Text>
        </View>
      )}
    </View>
  );
}

const styles = StyleSheet.create({
  base: { overflow: 'hidden', backgroundColor: Ink[100] },
  logoWrap: { backgroundColor: '#fff' },
  placeholder: { alignItems: 'center', justifyContent: 'center', backgroundColor: 'rgba(30,58,95,0.04)' },
});
