import { router } from 'expo-router';
import { Pressable, ScrollView, StyleSheet, Text, View } from 'react-native';
import { useSafeAreaInsets } from 'react-native-safe-area-context';

import { EmptyState } from '@/components/ui/EmptyState';
import { ShimmerCard } from '@/components/ui/Shimmer';
import { Accent, Brand, Ink, Radius, Shadow } from '@/constants/theme';
import { useAuth } from '@/hooks/use-auth';
import { useCompanyKpis } from '@/hooks/use-company-kpis';
import { useProfile } from '@/hooks/use-profile';

/** 今日の数字 — 開いて3秒で会社の状態が分かるホーム（社長・慧士さん共通） */

function yen(v: number): string {
  return '¥' + Math.round(v).toLocaleString();
}

function fmtShort(v: number): string {
  if (Math.abs(v) >= 1e8) return `${(v / 1e8).toFixed(2)}億円`;
  return `${Math.round(v / 1e4).toLocaleString()}万円`;
}

function monthLabel(month: string): string {
  return `${parseInt(month.slice(5, 7), 10)}月`;
}

export default function KeieiHomeScreen() {
  const insets = useSafeAreaInsets();
  const { session } = useAuth();
  const { profile } = useProfile(session);
  const { kpis, loading, error, reload } = useCompanyKpis();

  if (loading) {
    return (
      <View style={[styles.root, { paddingTop: insets.top + 16 }]}>
        <View style={styles.container}>
          <ShimmerCard />
          <ShimmerCard />
        </View>
      </View>
    );
  }

  if (error || !kpis || !kpis.latestMonth) {
    return (
      <View style={[styles.root, { paddingTop: insets.top + 16 }]}>
        <EmptyState icon="📊" title="データを読み込めませんでした" message={error ?? ''} actionLabel="再読み込み" onAction={reload} />
      </View>
    );
  }

  const latest = kpis.latestMonth;
  const prev = kpis.months.length >= 2 ? kpis.months[kpis.months.length - 2] : null;
  const momPct = prev && prev.total > 0 ? (latest.total / prev.total - 1) * 100 : null;
  const gpRate = latest.total > 0 ? latest.gpEst / latest.total : 0;
  const periodFrom = kpis.months[0]?.month ?? '';
  const isRangerViewer = profile?.role !== 'admin';

  return (
    <ScrollView style={styles.root} contentContainerStyle={{ paddingTop: insets.top + 16, paddingBottom: 32 }}>
      <View style={styles.container}>
        {/* ヘッダー */}
        <View style={styles.headerRow}>
          <View>
            <Text style={styles.brand}>マルイ物産</Text>
            <Text style={styles.title}>今日の数字</Text>
          </View>
          {isRangerViewer ? (
            <Pressable onPress={() => router.replace('/(tabs)')} style={styles.backChip}>
              <Text style={styles.backChipText}>レンジャー画面へ</Text>
            </Pressable>
          ) : null}
        </View>

        {/* 今月の売上（主役） */}
        <View style={styles.hero}>
          <Text style={styles.heroLabel}>{monthLabel(latest.month)}の全社売上</Text>
          <Text style={styles.heroValue}>{yen(latest.total)}</Text>
          <View style={styles.heroMetaRow}>
            {momPct != null ? (
              <View style={[styles.momBadge, { backgroundColor: momPct >= 0 ? 'rgba(16,185,129,0.18)' : 'rgba(239,68,68,0.18)' }]}>
                <Text style={[styles.momText, { color: momPct >= 0 ? '#6EE7B7' : '#FCA5A5' }]}>
                  前月比 {momPct >= 0 ? '+' : ''}{momPct.toFixed(0)}%
                </Text>
              </View>
            ) : null}
            <Text style={styles.heroSub}>卸 {fmtShort(latest.wholesale)} ／ EC {fmtShort(latest.ec)}</Text>
          </View>
        </View>

        {/* 粗利・累計 */}
        <View style={styles.cardRow}>
          <View style={styles.kpiCard}>
            <Text style={styles.kpiLabel}>{monthLabel(latest.month)}の推定粗利</Text>
            <Text style={[styles.kpiValue, { color: Accent.emerald }]}>{fmtShort(latest.gpEst)}</Text>
            <Text style={styles.kpiSub}>粗利率 {(gpRate * 100).toFixed(1)}%</Text>
          </View>
          <View style={styles.kpiCard}>
            <Text style={styles.kpiLabel}>{monthLabel(periodFrom)}からの累計</Text>
            <Text style={styles.kpiValue}>{fmtShort(kpis.totalSales)}</Text>
            <Text style={styles.kpiSub}>粗利 {fmtShort(kpis.totalGpEst)}</Text>
          </View>
        </View>

        {/* 気になる数字 */}
        <View style={styles.alertCard}>
          <Text style={styles.alertTitle}>⚠️ 気になる数字</Text>
          {kpis.lossCount > 0 ? (
            <View style={styles.alertRow}>
              <Text style={styles.alertMain}>売るほど赤字（逆ざや）の商品が {kpis.lossCount} 品</Text>
              {kpis.lossTop.slice(0, 3).map((p) => (
                <Text key={p.code} style={styles.alertItem}>
                  ・{p.name}（{((p.gpRate ?? 0) * 100).toFixed(1)}%）
                </Text>
              ))}
            </View>
          ) : (
            <Text style={styles.alertMain}>逆ざや商品はありません</Text>
          )}
          {kpis.unmappedAmount > 0 ? (
            <Text style={styles.alertFoot}>
              原価がまだ紐づいていない売上：{fmtShort(kpis.unmappedAmount)}（粗利は含まれていません）
            </Text>
          ) : null}
        </View>

        {/* 詳細へ */}
        <Pressable onPress={() => router.push('/keiei/kanri')} style={({ pressed }) => [styles.cta, pressed && { opacity: 0.85 }]}>
          <Text style={styles.ctaText}>経営管理をくわしく見る →</Text>
        </Pressable>

        <Text style={styles.note}>
          粗利は実質原価ベースの参考値（輸入品=原価表フルコスト、国内品=仕入実績）。データ期間: {periodFrom.replace('-', '年')}月〜{latest.month.replace('-', '年')}月
        </Text>
      </View>
    </ScrollView>
  );
}

const styles = StyleSheet.create({
  root: { flex: 1, backgroundColor: '#FAF7F0' },
  container: { width: '100%', maxWidth: 560, alignSelf: 'center', paddingHorizontal: 18, gap: 14 },

  headerRow: { flexDirection: 'row', justifyContent: 'space-between', alignItems: 'flex-end', marginBottom: 2 },
  brand: { fontSize: 12, fontWeight: '700', color: Ink[400], letterSpacing: 1 },
  title: { fontSize: 24, fontWeight: '900', color: Brand.navy },
  backChip: { paddingVertical: 7, paddingHorizontal: 12, borderRadius: 999, backgroundColor: '#fff', borderWidth: 1, borderColor: Ink[200] },
  backChipText: { fontSize: 12, fontWeight: '700', color: Ink[600] },

  hero: { backgroundColor: Brand.navy, borderRadius: Radius.lg, padding: 22, ...Shadow.card },
  heroLabel: { color: 'rgba(255,255,255,0.75)', fontSize: 14, fontWeight: '700', marginBottom: 6 },
  heroValue: { color: '#fff', fontSize: 38, fontWeight: '900', letterSpacing: -0.5 },
  heroMetaRow: { flexDirection: 'row', alignItems: 'center', gap: 10, marginTop: 12, flexWrap: 'wrap' },
  momBadge: { paddingVertical: 4, paddingHorizontal: 10, borderRadius: 999 },
  momText: { fontSize: 13, fontWeight: '800' },
  heroSub: { color: 'rgba(255,255,255,0.65)', fontSize: 13, fontWeight: '600' },

  cardRow: { flexDirection: 'row', gap: 12 },
  kpiCard: { flex: 1, backgroundColor: '#fff', borderRadius: Radius.lg, padding: 16, ...Shadow.card },
  kpiLabel: { fontSize: 12, fontWeight: '700', color: Ink[500], marginBottom: 6 },
  kpiValue: { fontSize: 22, fontWeight: '900', color: Ink[900] },
  kpiSub: { fontSize: 12, fontWeight: '600', color: Ink[500], marginTop: 4 },

  alertCard: { backgroundColor: '#fff', borderRadius: Radius.lg, padding: 18, borderWidth: 1, borderColor: 'rgba(245,158,11,0.35)', ...Shadow.card },
  alertTitle: { fontSize: 15, fontWeight: '800', color: Ink[900], marginBottom: 10 },
  alertRow: { gap: 4 },
  alertMain: { fontSize: 14, fontWeight: '700', color: Accent.red },
  alertItem: { fontSize: 13, color: Ink[700], lineHeight: 20 },
  alertFoot: { fontSize: 12, color: Ink[500], marginTop: 10, lineHeight: 18 },

  cta: { backgroundColor: Brand.navy, borderRadius: Radius.md, paddingVertical: 16, alignItems: 'center' },
  ctaText: { color: '#fff', fontSize: 16, fontWeight: '800' },

  note: { fontSize: 11, color: Ink[400], lineHeight: 17 },
});
