import { Redirect, Tabs } from 'expo-router';
import { ActivityIndicator, Platform, Text, View } from 'react-native';

import { Brand, Ink } from '@/constants/theme';
import { useAuth } from '@/hooks/use-auth';
import { useProfile } from '@/hooks/use-profile';

/**
 * 経営管理画面（社長＋executive_viewer専用）。
 * スマホファーストの下部2タブ。PCでも同じ構成（中央寄せで幅制限のみ）。
 * レンジャー画面とは独立したルートグループ。
 */
export default function KeieiLayout() {
  const { session, loading } = useAuth();
  const { profile, loading: profileLoading } = useProfile(session);

  if (loading || (session && profileLoading)) {
    return (
      <View style={{ flex: 1, justifyContent: 'center', alignItems: 'center', backgroundColor: '#FAF7F0' }}>
        <ActivityIndicator color={Brand.navy} />
      </View>
    );
  }

  if (!session) {
    return <Redirect href="/login" />;
  }

  const allowed = profile?.role === 'admin' || profile?.executive_viewer;
  if (!allowed) {
    return <Redirect href="/(tabs)" />;
  }

  return (
    <Tabs
      screenOptions={{
        headerShown: false,
        tabBarActiveTintColor: Brand.navy,
        tabBarInactiveTintColor: Ink[400],
        tabBarLabelStyle: { fontSize: 12, fontWeight: '700', paddingBottom: Platform.OS === 'web' ? 6 : 0 },
        tabBarStyle: {
          height: 62,
          paddingTop: 6,
          backgroundColor: '#fff',
          borderTopColor: Ink[100],
        },
      }}
    >
      <Tabs.Screen
        name="index"
        options={{
          title: '今日の数字',
          tabBarIcon: ({ focused }) => (
            <Text style={{ fontSize: 20, opacity: focused ? 1 : 0.45 }}>📊</Text>
          ),
        }}
      />
      <Tabs.Screen
        name="kanri"
        options={{
          title: '経営管理',
          tabBarIcon: ({ focused }) => (
            <Text style={{ fontSize: 20, opacity: focused ? 1 : 0.45 }}>📈</Text>
          ),
        }}
      />
    </Tabs>
  );
}
