import * as Updates from 'expo-updates';
import { useEffect } from 'react';
import { AppState, Platform } from 'react-native';

const VERSION_KEY = 'app_version';
const VERSION_URL = '/marui-ranger-app/version.txt';

// リロードしてよいのは「起動/復帰の直後」だけ。それ以降に
// ダウンロードが完了した場合は放置し、次の起動/復帰で適用する
// (入力中に画面が突然リロードされるのを避ける)。
const APPLY_WINDOW_MS = 10_000;
let lastBecameActiveAt = Date.now();

/**
 * 自動更新チェック
 *
 * Web(PWA): version.txt を起動・復帰・10分おきに比較し、変わっていたら
 * サイレントリロード。
 *
 * ネイティブ(iPhone): expo-updates のOTA更新を自動適用する。
 * 従来は「起動時にDL→次回起動で適用」のため反映に2回起動が必要で、
 * しかもiPhoneはアプリを完全終了することが滅多にないので
 * 何日も古いままになりがちだった(慧士さんFB 2026-07-13)。
 * ①起動直後にDLが終わったら即リロード ②フォアグラウンド復帰時にも
 * チェック→DL→復帰直後なら即リロード、で常に1回の起動/復帰で最新になる。
 * リロードしてもログインセッション(AsyncStorage)はそのまま保持される。
 */
export function useAutoUpdate() {
  // ネイティブ: 起動時のバックグラウンドDL(checkAutomatically既定)が
  // 完了したタイミングで、起動直後なら即適用
  const { isUpdatePending } = Updates.useUpdates();

  useEffect(() => {
    if (Platform.OS === 'web' || !Updates.isEnabled) return;
    if (!isUpdatePending) return;
    if (Date.now() - lastBecameActiveAt < APPLY_WINDOW_MS) {
      Updates.reloadAsync();
    }
  }, [isUpdatePending]);

  // ネイティブ: フォアグラウンド復帰時にチェック
  useEffect(() => {
    if (Platform.OS === 'web' || !Updates.isEnabled) return;

    const sub = AppState.addEventListener('change', async (state) => {
      if (state !== 'active') return;
      lastBecameActiveAt = Date.now();
      try {
        const check = await Updates.checkForUpdateAsync();
        if (!check.isAvailable) return;
        await Updates.fetchUpdateAsync();
        if (Date.now() - lastBecameActiveAt < APPLY_WINDOW_MS) {
          await Updates.reloadAsync();
        }
      } catch {
        // ネットワークエラー等は無視(次の復帰で再チェック)
      }
    });
    return () => sub.remove();
  }, []);

  // Web(PWA): version.txt ベースの自動リロード
  useEffect(() => {
    if (Platform.OS !== 'web') return;
    if (typeof window === 'undefined') return;

    async function check() {
      try {
        const res = await fetch(`${VERSION_URL}?t=${Date.now()}`, { cache: 'no-store' });
        if (!res.ok) return;
        const remote = (await res.text()).trim();
        if (!remote) return;
        const local = window.localStorage.getItem(VERSION_KEY);
        if (!local) {
          window.localStorage.setItem(VERSION_KEY, remote);
          return;
        }
        if (local !== remote) {
          window.localStorage.setItem(VERSION_KEY, remote);
          // キャッシュ無視で再読み込み
          window.location.reload();
        }
      } catch {
        // ネットワークエラー等は無視
      }
    }

    check();

    const onVisible = () => {
      if (document.visibilityState === 'visible') check();
    };
    document.addEventListener('visibilitychange', onVisible);

    // 定期チェック（10分おき、バックグラウンドから戻らなくても反映）
    const id = window.setInterval(check, 10 * 60 * 1000);

    return () => {
      document.removeEventListener('visibilitychange', onVisible);
      window.clearInterval(id);
    };
  }, []);
}
