import { useState } from 'react';
import { Platform, TextInput, type TextInputProps } from 'react-native';

type Props = TextInputProps & {
  /** 最小の高さ(px)。デフォルト44(1行分の通常入力欄と同じ高さ) */
  minHeight?: number;
  /** これ以上は伸びない上限(px)。デフォルト600 */
  maxHeight?: number;
};

/**
 * 入力量に合わせて高さが自動で伸びる複数行TextInput。
 *
 * 固定高さ+内部スクロールだと、スマホで4行を超えたあたりから
 * 「自分がどこを打っているか分からない」状態になる(松永さんFB 2026-07-10)。
 * scrollEnabled=false で内部スクロールを殺し、欄自体を伸ばして
 * ページ側のスクロールに任せることでカーソルが常に見える。
 *
 * 高さの決め方はプラットフォームで別:
 *  - ネイティブ(New Architecture): 高さを指定しなければ内容に合わせて
 *    自動で伸縮する。onContentSizeChangeで高さを設定してはいけない —
 *    iOSはscrollEnabled=falseだとcontentSize=欄の高さを返すので、
 *    「高さを設定→contentSizeが増える→また設定」のループで
 *    maxHeightまで育つ(空欄なのに600pxになっていた不具合の原因)
 *  - web(react-native-web): textareaは自動で伸びないので、
 *    scrollHeight(padding込み)をそのまま高さにする(値が一致したら
 *    イベントが来なくなるためループしない)
 */
export function AutoGrowTextInput({ minHeight = 44, maxHeight = 600, style, ...rest }: Props) {
  const [webHeight, setWebHeight] = useState(minHeight);
  const isWeb = Platform.OS === 'web';

  return (
    <TextInput
      {...rest}
      multiline
      scrollEnabled={false}
      onContentSizeChange={
        isWeb
          ? (e) => {
              const h = Math.ceil(e.nativeEvent.contentSize.height);
              setWebHeight(Math.min(maxHeight, Math.max(minHeight, h)));
            }
          : undefined
      }
      style={[
        style,
        { minHeight, maxHeight, textAlignVertical: 'top' },
        isWeb ? { height: webHeight } : null,
      ]}
    />
  );
}
